lessons.solution_code:
export interface ApiResponse<T> {
    data: T;
    status: number;
}

export function wrapData<T>(data: T): ApiResponse<T> {
    return { data, status: 200 };
}

tests.unittest_code:
const num = solution.wrapData(5);
if (num.status !== 200 || num.data !== 5) throw new Error('number wrap failed');
const res = solution.wrapData({ ok: true });
if (res.status !== 200 || !res.data.ok) throw new Error('object wrap failed');

