lessons.solution_code:
export class Server {
    readonly port: number;

    constructor(port: number) {
        this.port = port;
    }

    portAddress(): string {
        return `http://localhost:${this.port}`;
    }
}

tests.unittest_code:
const s = new solution.Server(8080);
if (s.port !== 8080) throw new Error('port field');
if (s.portAddress() !== 'http://localhost:8080') throw new Error('address');

